"use strict";
window.runHomeInteractions = async ctx => {
    const { plugin, mount, current, load, settle, check, files, contents, pages, metadataCache, index } = ctx;
    const actual = plugin.taskService, gates = []; let delay = false, fail = false, queryCalls = 0;
    plugin.taskService = { subscribe: actual.subscribe.bind(actual), close: actual.close.bind(actual), resolveLegacyAction: actual.resolveLegacyAction.bind(actual), resolveReveal: actual.resolveReveal.bind(actual),
        queryStructured: async options => { queryCalls++; if (fail) throw Error("Deterministic Home query failure"); const result = await actual.queryStructured(options);
            if (delay) await new Promise(resolve => gates.push(resolve)); return result; } };
    const invalidate = async () => { plugin.taskData.invalidateAll(); await settle(); };
    const waitGate = async () => { for (let i = 0; i < 300 && !gates.length; i++) await Promise.resolve(); assert(gates.length, "Delayed Home query started"); };
    const rows = instance => [...instance.root.querySelectorAll(".home-task-row")];
    const rowFor = (instance, title) => rows(instance).find(row => row.querySelector(".home-task-text")?.textContent === title);
    const tasks = instance => [...instance.controller.projects, ...instance.controller.resources];
    const live = await mount(current), initialRows = rows(live), initialProgress = live.context.progress ?? 0;
    await invalidate(); check(rows(live).every((row, i) => row === initialRows[i]), "Unchanged task invalidation retains actual row nodes");
    check((live.context.progress ?? 0) === initialProgress, "Task invalidation performs no secondary Progress work");
    let row = rowFor(live, "Unscheduled"), box = row.querySelector("input"); box.focus();
    plugin.projectWizard.data.taskMetadata.unscheduled = { necessity: "must" }; await invalidate();
    check(document.activeElement === rowFor(live, "Unscheduled").querySelector("input"), "Focused checkbox survives changed projection");
    delay = true; await invalidate(); await waitGate(); ctx.setImportPaused(true);
    box = rowFor(live, "Unscheduled").querySelector("input"); box.checked = true; box.dispatchEvent(new Event("change", { bubbles: true })); await settle();
    check(tasks(live).find(item => item.task.hubTaskId === "unscheduled").task.completed, "Actual Home checkbox immediately publishes writer completion");
    gates.splice(0).forEach(resolve => resolve()); delay = false; await settle(); await live.controller.load();
    check(tasks(live).find(item => item.task.hubTaskId === "unscheduled").task.completed, "Old query and lagging import cannot revert completion");
    const path = "Projects/App/Tasks/Unscheduled.md"; index(files.get(path)); metadataCache.emit("dataview:metadata-change", "update", files.get(path)); ctx.setImportPaused(false); await settle();
    check(ctx.facts().history.length === 1 && ctx.facts().oathChanges === 1, "Exactly one actual completion event and Oath feedback");
    [...live.root.querySelectorAll(".hub-task-group-toggle")].find(button => button.textContent.includes("completed")).click(); await settle();
    box = rowFor(live, "Unscheduled").querySelector("input"); box.checked = false; box.dispatchEvent(new Event("change", { bubbles: true })); await settle();
    check(!tasks(live).find(item => item.task.hubTaskId === "unscheduled").task.completed, "Actual Home checkbox reopens through original writer");
    row = rowFor(live, "Assignment\ncontinuation evidence"); row.querySelector(".hub-task-steps-toggle").click(); await settle();
    const step = row.querySelectorAll(".hub-task-step-item input")[1]; ctx.setImportPaused(true); delay = true; await invalidate(); await waitGate();
    step.checked = true; step.dispatchEvent(new Event("change", { bubbles: true })); await settle(); gates.splice(0).forEach(resolve => resolve()); delay = false; await settle(); await live.controller.load();
    check(contents.get("Projects/App/Tasks/Continuation.md").includes("[x] Next") && tasks(live).find(item => item.task.hubTaskId === "assignment").task.steps.every(step => step.completed), "Actual nested Step writer and immediate state survive delayed query/import");
    check(live.root.querySelector(".hub-task-steps-toggle[aria-expanded='true']"), "Step disclosure survives completion refresh");
    index(files.get("Projects/App/Tasks/Continuation.md")); metadataCache.emit("dataview:metadata-change", "update", files.get("Projects/App/Tasks/Continuation.md")); ctx.setImportPaused(false); await settle();
    rowFor(live, "Unscheduled").querySelector(".home-task-text").dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true })); await settle();
    const modal = window.lastModal, title = modal.contentEl.querySelector("textarea"); title.focus(); title.value = "Pending Home draft"; title.dispatchEvent(new Event("input", { bubbles: true }));
    const callsBefore = queryCalls; await invalidate(); check(title.isConnected && title.value === "Pending Home draft" && document.activeElement === title && queryCalls === callsBefore, "Task editor draft and focus defer task reads");
    modal.modalEl.querySelector(".modal-close-button").click(); await settle();
    check(queryCalls > callsBefore, "Click dismissal resumes deferred task reads without another interaction");
    row = rowFor(live, "Assignment\ncontinuation evidence"); row.querySelector(".home-task-text").click(); await settle();
    const stepModal = window.lastModal; stepModal.contentEl.querySelector('[aria-label^="Edit Step:"]')?.click();
    const stepDraft = stepModal.contentEl.querySelector('textarea[aria-label="Step text"]'); assert(stepDraft, "Existing Step editor is available");
    stepDraft.value = "Pending Step draft"; stepDraft.focus(); await invalidate(); check(stepDraft.isConnected && stepDraft.value === "Pending Step draft" && document.activeElement === stepDraft, "Step draft and focus survive invalidation");
    stepModal.close(); document.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); await settle();
    rowFor(live, "Unscheduled").dispatchEvent(new MouseEvent("contextmenu", { bubbles: true, clientX: 40, clientY: 40 })); await settle();
    const menu = document.querySelector(".menu"), oldRows = rows(live); await invalidate();
    check(menu.isConnected && rows(live).every((row, i) => row === oldRows[i]), "Open native context menu and rows survive invalidation");
    [...menu.querySelectorAll("button")].find(button => button.textContent === "Add task below").click(); await settle();
    const inline = live.root.querySelector(".hub-task-editor"); inline.value = "Pending inline Home draft"; inline.focus(); await invalidate();
    check(inline.isConnected && inline.value === "Pending inline Home draft" && document.activeElement === inline, "Inline draft and focus survive invalidation");
    inline.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); await settle();
    fail = true; await invalidate(); check(live.root.querySelector('[role="status"]') && tasks(live).length > 0, "Query failure retains last valid Home rows with restrained status");
    await invalidate(); check(live.root.querySelectorAll('[role="status"]').length === 1, "Repeated failure does not duplicate status");
    fail = false; await invalidate(); check(!live.root.querySelector('[role="status"]'), "Later invalidation recovers and removes error status");
    rowFor(live, "Unscheduled").querySelector(".home-task-location").click(); await settle();
    check(live.context.opened === path, "Actual Home source opening uses fresh validated reference");
    const progressBefore = live.context.progress ?? 0; await invalidate(); check((live.context.progress ?? 0) === progressBefore, "Completion/import refreshes stay isolated from secondary panels");
    rowFor(live, "Unscheduled").dispatchEvent(new MouseEvent("contextmenu", { bubbles: true, clientX: 40, clientY: 40 })); await settle();
    [...document.querySelectorAll(".menu button")].find(button => button.textContent === "Add task below").click(); await settle();
    const closingDraft = live.root.querySelector(".hub-task-editor"); closingDraft.value = "Saved while Home closes"; live.dispose(); await settle();
    check([...contents.values()].some(text => text.includes("Saved while Home closes")), "Actual accepted inline cleanup commit survives Home disposal");
    delay = true; const a = await mount(current, false); await waitGate(); a.dispose(); delay = false;
    const b = await mount(current); const before = b.root.innerHTML; gates.splice(0).forEach(resolve => resolve()); await settle();
    check(b.root.innerHTML === before, "Obsolete Home instance cannot publish into a fresh mount"); b.dispose();
    for (let i = 0; i < 10; i++) { const instance = await mount(current); instance.dispose(); }
    check(plugin.taskData.subscribers.size === 0, "Repeated mounts release every owned subscriber");
    plugin.taskService = actual;
};
